import Foundation
import CryptoKit

// MARK: - Configuration Registry (Singleton)
class CryptoConfigRegistry {
    static let shared = CryptoConfigRegistry()
    private var properties: [String: Any] = [
        "algorithm": "AES-GCM-256",
        "keyDerivation": "HKDF-SHA256",
        "iterations": 100000,
        "allowRawKeyImport": false,
        "maxPayloadSize": 10_485_760,
        "trustedUploaders": ["system", "admin"]
    ]

    private init() {}

    func get(_ keyPath: String) -> Any? {
        let components = keyPath.split(separator: ".").map(String.init)
        return resolveKeyPath(components, in: properties)
    }

    func set(_ keyPath: String, value: Any) {
        let components = keyPath.split(separator: ".").map(String.init)
        setNestedValue(components, value: value, in: &properties)
    }

    private func resolveKeyPath(_ components: [String], in dict: [String: Any]) -> Any? {
        guard let first = components.first else { return nil }
        if components.count == 1 {
            return dict[first]
        }
        if let nested = dict[first] as? [String: Any] {
            return resolveKeyPath(Array(components.dropFirst()), in: nested)
        }
        return nil
    }

    private func setNestedValue(_ components: [String], value: Any, in dict: inout [String: Any]) {
        guard let first = components.first else { return }
        if components.count == 1 {
            dict[first] = value
            return
        }
        var nested = dict[first] as? [String: Any] ?? [:]
        setNestedValue(Array(components.dropFirst()), value: value, in: &nested)
        dict[first] = nested
    }
}

// MARK: - Upload Metadata Parser
struct UploadMetadata {
    let fields: [String: Any]
}

class MetadataParser {
    func parse(jsonData: Data) throws -> UploadMetadata {
        guard let json = try JSONSerialization.jsonObject(with: jsonData) as? [String: Any] else {
            throw MetadataError.invalidFormat
        }
        return UploadMetadata(fields: json)
    }
}

enum MetadataError: Error {
    case invalidFormat
    case invalidField(String)
}

// MARK: - Upload Processor
class CryptoUploadProcessor {
    private let registry = CryptoConfigRegistry.shared
    private let parser = MetadataParser()

    private let allowedMetadataKeys: Set<String> = [
        "filename", "contentType", "encoding",
        "checksum", "timestamp", "uploaderHint",
        "cryptoParams"
    ]

    func processUpload(payload: Data, metadata: Data) throws -> ProcessedUpload {
        let meta = try parser.parse(jsonData: metadata)

        // Apply user-specified crypto parameters to registry
        try applyUserCryptoParams(meta.fields)

        // Verify upload authorization
        guard isAuthorized() else {
            throw ProcessingError.unauthorized
        }

        // Process the cryptographic payload
        return try decryptPayload(payload)
    }

    private func applyUserCryptoParams(_ fields: [String: Any]) throws {
        guard let cryptoParams = fields["cryptoParams"] as? [String: Any] else {
            return // No custom params, use defaults
        }

        let allowedCryptoKeys: Set<String> = ["nonce", "tag", "aad", "keyId"]

        for (key, value) in cryptoParams {
            // Validate key is in allowed set
            guard allowedCryptoKeys.contains(key) || key.hasPrefix("x-custom-") else {
                throw MetadataError.invalidField(key)
            }
            // Store in registry under cryptoParams namespace
            registry.set("cryptoParams.\(key)", value: value)
        }
    }

    private func isAuthorized() -> Bool {
        guard let allowed = registry.get("allowRawKeyImport") as? Bool else {
            return false
        }
        // Only process if raw key import is disabled (secure default)
        return !allowed
    }

    private func decryptPayload(_ payload: Data) throws -> ProcessedUpload {
        guard let algorithm = registry.get("algorithm") as? String else {
            throw ProcessingError.configError
        }

        let symmetricKey = SymmetricKey(size: .bits256)

        switch algorithm {
        case "AES-GCM-256":
            let sealedBox = try AES.GCM.SealedBox(combined: payload)
            let decrypted = try AES.GCM.open(sealedBox, using: symmetricKey)
            return ProcessedUpload(data: decrypted, algorithm: algorithm)
        default:
            throw ProcessingError.unsupportedAlgorithm
        }
    }
}

struct ProcessedUpload {
    let data: Data
    let algorithm: String
}

enum ProcessingError: Error {
    case unauthorized
    case configError
    case unsupportedAlgorithm
    case decryptionFailed
}

// MARK: - Extended metadata processing for batch uploads
extension CryptoUploadProcessor {
    func processBatchMetadata(_ metadataList: [Data]) throws {
        for metadataItem in metadataList {
            let meta = try parser.parse(jsonData: metadataItem)
            try applyExtendedFields(meta.fields)
        }
    }

    private func applyExtendedFields(_ fields: [String: Any]) throws {
        for (key, value) in fields {
            guard allowedMetadataKeys.contains(key) else {
                continue
            }
            if key == "cryptoParams", let nested = value as? [String: Any] {
                for (nestedKey, nestedValue) in nested {
                    registry.set("\(key).\(nestedKey)", value: nestedValue)
                }
            }
        }
    }
}
